contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public {
        require(address(c).balance >= amount);

        address payable target = payable(address(this));
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;

        assert(c.depositsCount() == beforeCount && address(c).balance == beforeBal - amount);
    }

    receive() external payable {}
}

