pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.assume(address(c).balance >= amount);
        address payable target = payable(address(this));
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        try c.sendMoney(target, amount) {} catch { return; }
        assertTrue(c.depositsCount() == beforeCount && address(c).balance == beforeBal - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
